    byte[] bytes5 = { 0, 10 };
    String str5 = "*";
    assertEquals(str5, cMap.toUnicode(bytes5), "bytes 00 0A from bfchar <000A> <002A>");
    byte[] bytes6 = { 1, 10 };
    String str6 = "+";
    assertEquals(str6, cMap.toUnicode(bytes6), "bytes 01 0A from bfchar <010A> <002B>");
