@Test
void testGeneralGraphicStateOperatorTextMode() throws IOException {
    try (PDDocument doc = new PDDocument()) {
        PDPage page = new PDPage();
        doc.addPage(page);
        PDPageContentStream contentStream = new PDPageContentStream(doc, page);
        contentStream.beginText();
        PDImageXObject img1 = new PDImageXObject(doc);
        PDInlineImage img2 = new PDInlineImage(new COSDictionary(), new byte[0], new PDResources());
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.drawImage(img1, 0f, 0f, 1f, 1f));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.drawImage(img1, new Matrix()));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.drawImage(img2, 0f, 0f, 1f, 1f));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.addRect(0, 0, 1, 1));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.curveTo(0, 0, 1, 1, 2, 2));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.curveTo1(0, 0, 1, 1));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.curveTo2(0, 0, 1, 1));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.moveTo(0, 0));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.lineTo(1, 1));
        Assertions.assertThrows(IllegalStateException.class, () -> contentStream.shadingFill(new PDShadingType1(new COSDictionary())));
        Assertions.assertThrows(IllegalStateException.class, contentStream::stroke);
        Assertions.assertThrows(IllegalStateException.class, contentStream::closeAndStroke);
        Assertions.assertThrows(IllegalStateException.class, contentStream::closeAndFillAndStroke);
        Assertions.assertThrows(IllegalStateException.class, contentStream::closeAndFillAndStrokeEvenOdd);
        Assertions.assertThrows(IllegalStateException.class, contentStream::fill);
        Assertions.assertThrows(IllegalStateException.class, contentStream::fillAndStroke);
        Assertions.assertThrows(IllegalStateException.class, contentStream::fillAndStrokeEvenOdd);
        Assertions.assertThrows(IllegalStateException.class, contentStream::fillEvenOdd);
        Assertions.assertThrows(IllegalStateException.class, contentStream::closePath);
        Assertions.assertThrows(IllegalStateException.class, contentStream::clip);
        Assertions.assertThrows(IllegalStateException.class, contentStream::clipEvenOdd);
        // J
        contentStream.setLineCapStyle(0);
        // j
        contentStream.setLineJoinStyle(0);
        // w
        contentStream.setLineWidth(10f);
        // d
        contentStream.setLineDashPattern(new float[] { 2, 1 }, 0f);
        // M
        contentStream.setMiterLimit(1.0f);
        // gs
        contentStream.setGraphicsStateParameters(new PDExtendedGraphicsState());
        // ri, i are not supported with a specific setter
        contentStream.endText();
        contentStream.close();
    } catch (IllegalArgumentException exception) {
        fail(exception);
    }
}

